import numpy as np
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Quick screening: use simple correlation-based approach
    # Focus on top features by effect size
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        if len(feats.y) > 0:
            mean_1 = np.mean(feats.x[feats.y==1, i])
            mean_0 = np.mean(feats.x[feats.y==0, i])
            effect_size = abs(mean_1 - mean_0)
            effect_sizes.append((effect_size, fid))

    # Sort by effect size
    effect_sizes.sort(reverse=True)
    top_features = [fid for _, fid in effect_sizes[:20]]  # Take top 20

    # Quick correlation check for near-duplicates
    used = set()
    final_features = []

    for fid in top_features:
        if fid in used:
            continue
        # Check if this feature is correlated with already selected features
        is_duplicate = False
        fid_idx = feats.column(fid)
        if fid_idx < feats.x.shape[1]:  # Valid index
            for selected_fid in final_features:
                sel_idx = feats.column(selected_fid)
                if sel_idx < feats.x.shape[1]:
                    corr = np.corrcoef(feats.x[:, fid_idx], feats.x[:, sel_idx])[0,1]
                    if abs(corr) >= 0.6:
                        is_duplicate = True
                        break
        if not is_duplicate:
            final_features.append(fid)
            used.add(fid)
        if len(final_features) >= MAX_DRIVERS:
            break

    # Simple logistic regression to detect mechanism
    if len(final_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    try:
        X_selected = feats.x[:, [feats.column(fid) for fid in final_features if feats.column(fid) < feats.x.shape[1]]]
        model = LogisticRegression(penalty='l1', solver='liblinear', C=0.1, max_iter=100)
        model.fit(X_selected, feats.y)
        coefs = model.coef_[0]
        if np.any(np.abs(coefs) > 0.1):
            drivers = tuple(final_features)
            columns = tuple(final_features)
            loadings = {fid: coef for fid, coef in zip(final_features, coefs) if not np.isnan(coef)}
            return Design(drivers=drivers, columns=columns, products=(), loadings=loadings)
    except:
        pass

    return Design(drivers=(), columns=(), products=(), loadings={})
